field.eval:
{
 "type": "object",
 "properties": {
   "model": {"type": "string", "description": "Model name, e.g. purchase.order"},
   "domain": {"type": "array", "description": "Odoo domain as nested arrays", "default": []},
   "fields": {"type": "array", "items": {"type": "string"}, "default": ["name"]},
   "limit": {"type": "integer", "default": 10},
   "offset": {"type": "integer", "description": "Skip this many rows; use next_offset from the previous call", "default": 0},
   "order": {"type": "string", "description": "Sort, e.g. 'create_date desc, name'. Only real fields, asc or desc"},
"about": {"type": "string", "description": "What you are looking for, in words (e.g. 'overdue invoices with amounts'). Used to pick the most useful fields when you omit fields. Never name an id here."}
 },
 "required": ["model"]
}

{
 "type": "object",
 "properties": {
   "model": {"type": "string"},
   "res_id": {"type": "integer"},
   "res_ids": {"type": "array", "items": {"type": "integer"}, "description": "Up to 10 ids instead of res_id"},
   "fields": {"type": "array", "items": {"type": "string"}},
   "about": {"type": "string", "description": "What you want to know, in words. Used to pick the most useful fields when you omit fields."}
 },
 "required": ["model"]
}

{
 "type": "object",
 "properties": {
   "model": {"type": "string"},
   "values": {"type": "object", "description": "Field values for the new record"},
   "force": {"type": "boolean", "description": "Leads only: set true when the user confirms creating a duplicate after the already-exists question. Never set pre-emptively."}
 },
 "required": ["model", "values"]
}

{
 "type": "object",
 "properties": {
   "model": {"type": "string"},
   "res_id": {"type": "integer"},
   "field": {"type": "string", "description": "One2many field name, e.g. order_line"},
   "res_ids": {"type": "array", "items": {"type": "integer"}, "description": "Up to 10 ids instead of res_id"},
   "fields": {"type": "array", "items": {"type": "string"}},
   "limit": {"type": "integer"},
   "offset": {"type": "integer", "description": "Skip this many lines; use next_offset from the previous call", "default": 0},
   "order": {"type": "string", "description": "Sort lines, e.g. 'price_total desc'. Only real fields, asc or desc"}
 },
 "required": ["model", "res_id", "field"]
}

{
 "type": "object",
 "properties": {
   "model": {"type": "string"},
   "res_id": {"type": "integer"},
   "method": {"type": "string", "description": "Public method name, e.g. action_confirm"},
   "args": {"type": "array", "description": "Optional positional arguments"}
 },
 "required": ["model", "res_id", "method"]
}

{
 "type": "object",
 "properties": {
   "model": {"type": "string"},
   "query": {"type": "string", "description": "Substring to match against field names and labels, e.g. 'date'"},
   "fields": {"type": "array", "items": {"type": "string"}, "description": "Exact field names to return"}
 },
 "required": ["model"]
}

{
 "type": "object",
 "properties": {
   "model": {"type": "string"},
   "method": {"type": "string", "description": "Omit to list the model's business methods"}
 },
 "required": ["model"]
}

{
 "type": "object",
 "properties": {
   "question": {"type": "string", "description": "The clarifying question"},
   "header": {"type": "string", "description": "Optional short label (max 30 chars)"},
   "options": {"type": "array", "description": "1 to 6 clickable options, strings or {label, description}"}
 },
 "required": ["question", "options"]
}

{
 "type": "object",
 "properties": {
   "res_id": {"type": "integer", "description": "account.move id"},
   "amount": {"type": "number", "description": "Defaults to the open balance"},
   "journal_id": {"type": "integer", "description": "Defaults to the first bank journal"}
 },
 "required": ["res_id"]
}

{
 "type": "object",
 "properties": {
   "code": {"type": "string", "description": "Concept code from search_knowledge or the system prompt list"}
 },
 "required": ["code"]
}

{
 "type": "object",
 "properties": {
   "name": {"type": "string", "description": "Short title"},
   "kind": {"type": "string", "enum": ["skill", "memory", "wiki", "reference"], "default": "memory", "description": "skill = a procedure to follow; memory = a durable fact; wiki = a concept; reference = documentation"},
   "description": {"type": "string", "description": "One line describing when this applies - this is what gets matched against the request"},
   "body": {"type": "string", "description": "The content, in markdown"}
 },
 "required": ["name", "body"]
}

{
"type": "object",
"properties": {
"query": {"type": "string", "description": "Optional filter on the flow name or description"}
}
}

{
 "type": "object",
 "properties": {
   "flow": {"type": "string", "description": "Flow name from list_flows"},
   "arguments": {"type": "object", "description": "Values for the flow's input variables"}
 },
 "required": ["flow"]
}

{
"type": "object",
"properties": {
"model": {"type": "string", "description": "Model to filter"},
"conditions": {"type": "array", "description": "List of {field, operator, value}", "items": {"type": "object"}},
"match": {"type": "string", "enum": ["all", "any"], "default": "all", "description": "all = AND, any = OR"}
},
"required": ["model", "conditions"]
}

{
"type": "object",
"properties": {
"query": {"type": "string", "description": "Optional filter on the model name or label"}
}
}

{
"type": "object",
"properties": {
"model": {"type": "string", "description": "Model to write"},
"operation": {"type": "string", "enum": ["write", "create"], "default": "write"},
"res_id": {"type": "integer", "description": "Record id, for a write"},
"values": {"type": "object", "description": "Field values to write"}
},
"required": ["model", "values"]
}

{
"type": "object",
"properties": {
"model": {"type": "string", "description": "Model to write"},
"res_id": {"type": "integer", "description": "Record id to update"},
"values": {"type": "object", "description": "Field values to write: name, list_price, and the rest as a flat object"}
},
"required": ["model", "res_id", "values"]
}

{
"type": "object",
"properties": {
"model": {"type": "string"},
"operations": {"type": "array", "description": "Subset of read, write, create, unlink", "items": {"type": "string"}},
"res_id": {"type": "integer", "description": "Specific record to judge"},
"fields": {"type": "array", "description": "Field names to check for group gating", "items": {"type": "string"}}
},
"required": ["model"]
}

{
"type": "object",
"properties": {
"query": {"type": "string", "description": "Filter models by technical name, label or field"},
"model": {"type": "string", "description": "One model to read in full"},
"full": {"type": "boolean", "description": "Return full concept bodies, not just the catalogue"},
"limit": {"type": "integer", "default": 200}
}
}

{
"type": "object",
"properties": {
"name": {"type": "string", "description": "Flow name, e.g. Chase overdue invoices"},
"description": {"type": "string", "description": "One line: what it does"},
"steps": {"type": "array", "description": "Ordered steps: {type, config, resultVariable}. Types: start, search, read, create, tool, agent, note, output.", "items": {"type": "object"}}
},
"required": ["name", "steps"]
}

{
"type": "object",
"properties": {
"flow": {"type": "string", "description": "Flow name to revise"},
"description": {"type": "string"},
"nodes": {"type": "array", "description": "Full node list: {id, type, name, config}", "items": {"type": "object"}},
"edges": {"type": "array", "description": "Edges: {source, target, source_handle}", "items": {"type": "object"}},
"trigger": {"type": "object", "description": "{type: chat|schedule|webhook|record|manual, config: {...}}"}
},
"required": ["flow", "nodes"]
}
